import numpy as np

from mcf.research.arena.indicators import compute

SIDE = 'long'
GEOM = 't05s1'
WINDOW = (1400, 1500)          # bar close lo <= tod <= hi (inclusive, as the YAML window)
MIN_ADV = 20000000.0
CONTEXT = ['breadth']              # lab context columns (config `context:`), point-in-time per 5-minute bar
CONDS = [
    ('breadth', '>', 0.5),
    ('macd_hist', '>=', 0.12),
    ('ret3_atr', '<=', -0.069),
]
LAYERS = ['breadth > 0.5', 'macd_hist >= 0.12', 'ret3_atr <= -0.069', 'window 1400-1500', 'breadth change since 09:50 <= +0.20']


# Workbench gate (Mechanic 2026-11-16): market breadth must not have widened by more than BR_CHG_MAX since 09:50:
# br_chg = breadth at this bar - breadth at the 09:50 bar of the same session (owner rule: market-state gates are
# measured AFTER 09:50, vs the 09:50 state). Missing 09:50 value -> NaN -> no entry (fail safe).
BR_CHG_MAX = 0.20


def br_chg(df) -> np.ndarray:
    import pandas as pd
    if "breadth" not in df.columns:
        return np.full(len(df), np.nan)
    b = df["breadth"].to_numpy(dtype=float)
    tod = df["tod"].to_numpy(dtype=float)
    day = df["date"].astype(str).to_numpy() if "date" in df.columns else np.zeros(len(df), dtype=object)
    s = pd.Series(np.where(tod == 950, b, np.nan)).groupby(day).transform("max").to_numpy(dtype=float)
    return b - s


def mask(df) -> np.ndarray:
    x = compute(df, names=['macd_hist', 'ret3_atr'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
        m &= br_chg(df) <= BR_CHG_MAX
    return np.asarray(m, dtype=bool)
